public str getName()
{
    return fieldPName(RetailLoyaltyCard, LoyaltyBlockedDate);
}

public Set getAllowedValues()
{
    RetailLoyaltyCard   retailLoyaltyCard;
    var                 ret = new Set(Types::Date);

    while select LoyaltyBlockedDate from retailLoyaltyCard
        group by LoyaltyBlockedDate
    {
        ret.add(retailLoyaltyCard.LoyaltyBlockedDate);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailLoyaltyCard, LoyaltyBlockedDate));
    qbr.value(queryValue(_value));
}
